SELECT DISTINCT T1.Fname 
FROM Student AS T1 
JOIN Has_Pet AS T2 ON T1.StuID = T2.StuID 
WHERE EXISTS (
    SELECT 1 FROM Pets AS T3 WHERE T3.PetID IN (
        SELECT T4.PetID FROM Has_Pet AS T4 JOIN Pets AS T5 ON T4.PetID = T5.PetID WHERE T5.PetType = 'Cat'
    )
)
AND EXISTS (
    SELECT 1 FROM Pets AS T6 WHERE T6.PetID IN (
        SELECT T7.PetID FROM Has_Pet AS T7 JOIN Pets AS T8 ON T7.PetID = T8.PetID WHERE T8.PetType = 'Dog'
    )
);
```

